    return [
        'rename' => ['prepare' => null, 'act' => static fn (Node $node, DriveHandle $drive) => $drive->nodes()->rename($node->getKey(), 'Renamed', expectedSequence: 0)],
        'move' => ['prepare' => null, 'act' => static function (Node $node, DriveHandle $drive): void {
