    $node = RaceFixtures::document();
    $update = static fn (string $text) => app(UpdateDocumentContentAction::class)->execute(
        DocumentTestHelpers::context($node), new UpdateDocumentContentInput(node: $node, content: DocumentTestHelpers::content($text)),
30→    );
    $update('newer');
    $newer = DocumentTestHelpers::head($node);
    // A revision written by a newer release of the type: this installation shows it but cannot edit it.
    app(VaulterDatabase::class)->write(fn () => DocumentRevision::query()->whereKey($newer->getKey())->update(['schema_version' => 99]));
    $update('current');

    $results = RaceFixtures::race([
        static fn (): array => RaceFixtures::attempt(static fn () => $update('late edit')),
        static fn (): array => RaceFixtures::attempt(static fn () => app(RestoreDocumentRevisionAction::class)->execute(
40→            DocumentTestHelpers::context($node), new RestoreDocumentRevisionInput(node: $node, revision: $newer),
        )),
    ]);

    $document = DocumentTestHelpers::document($node);
    expect($results[1]['kind'])->toBe('committed')
        ->and($results[0]['kind'])->toBeIn(['committed', 'document_content_degraded'])
        // Whichever order, the restore has the last word: its schema, its content, a fenced epoch.
        ->and($document->schema_version)->toBe(99)
        ->and($document->collab_epoch)->toBe(1)
50→        ->and($document->tipTapContent()->toArray())->toBe(DocumentTestHelpers::content('newer')->toArray())
        ->and($document->yjs_state)->toBeNull();

    if ($results[0]['kind'] === 'document_content_degraded') {
